from common import *
src('igeeks-v3'); dom('css')
topic('Typography & Color')
M('b','k',"Which CSS property changes the colour of text?","color","text-color","font-color","foreground","The color property sets the text (foreground) colour. background-color sets the fill behind it.")
M('b','k',"Which CSS property sets the colour behind an element's content?","background-color","bgcolor","color-background","fill","background-color paints the element's background. color is for text.")
M('b','k',"Which property makes text bold?","font-weight","text-style","font-bold","text-weight","font-weight: bold (or a number such as 700) sets the thickness of the letters.")
M('b','k',"Which property sets the size of text?","font-size","text-size","font-height","size","font-size accepts units such as px, em and rem.")
M('b','k',"Which declaration centres text horizontally inside its container?","text-align: center","align: center","text-position: middle","horizontal-align: center","text-align controls the horizontal alignment of inline content in a block.")
M('b','k',"Which unit is relative to the font size of the root html element?","rem","em","px","pt","rem means root em, so it does not compound through nested elements like em does.")
topic('Selectors & Specificity')
M('b','k',"Which symbol starts a class selector?",".","#","*","@","A class selector is written .name. An id selector uses #name.")
M('b','k',"Which symbol starts an id selector?","#",".","&","$","#header selects the element with id='header'.")
M('b','k',"How is a comment written in CSS?","/* comment */","// comment","<!-- comment -->","# comment","CSS only supports /* ... */ comments.")
topic('Box Model')
M('b','k',"Which property adds space between an element's content and its border?","padding","margin","spacing","gap","Padding is inside the border. Margin is outside it.")
M('b','k',"Which property adds space outside an element's border?","margin","padding","outline","border-spacing","Margin separates the element from its neighbours.")
M('b','k',"Which property rounds the corners of a box?","border-radius","corner-radius","border-round","box-curve","border-radius: 8px rounds all four corners. 50% on a square makes a circle.")
topic('Positioning & Layout')
M('b','k',"Which value of display removes an element from the layout completely so it takes no space?","none","hidden","collapse","invisible","display: none removes the element from layout. visibility: hidden hides it but keeps its space.")
M('i','k',"A rule in an id selector and a rule in a class selector both set the colour of the same element. Which wins, assuming nothing else differs?","The id selector","The class selector","The one written first","The one written last","An id selector has higher specificity than a class selector, so it wins regardless of order.")
M('i','k',"An element has position: absolute. Relative to what is it positioned?","The nearest ancestor that has a position other than static","Its parent element always","The browser window always","Its previous sibling","If no ancestor is positioned, the initial containing block (the viewport area) is used.")
M('i','k',"In a flex container with the default direction, which property spaces items along the main axis?","justify-content","align-items","align-content","flex-wrap","justify-content works along the main axis (horizontal by default). align-items works across it.")
M('i','k',"What does box-sizing: border-box change?","The width and height include padding and border","The margin is included in the width","The border is removed","The box can no longer overflow","With border-box, width: 200px stays 200px even after padding and border are added.")
M('i','k',"Which selector chooses every even-numbered child of its parent?",":nth-child(2n)",":nth-child(2)",":even",":child(even)","2n matches positions 2, 4, 6 and so on. :nth-child(2) matches only the second child.")
M('i','k',"Which unit is a percentage of the viewport width?","vw","vh","rem","pc","1vw is 1% of the viewport width. vh is 1% of its height.")
M('i','k',"On which elements does z-index have an effect by default?","Positioned elements (and flex or grid items)","Only absolutely positioned elements","Every element","Only elements with a background","z-index is ignored on non-positioned elements unless they are flex or grid items.")
topic('Box Model')
M('a','o',"Two sibling blocks are stacked. The first has margin-bottom: 20px and the second has margin-top: 30px. What is the vertical gap between them?","30px","50px","20px","10px","Adjoining vertical margins collapse to the larger of the two, so the gap is 30px.")
topic('Positioning & Layout')
M('a','k',"Which declaration creates a new stacking context on an element that is otherwise not positioned?","opacity: 0.99","color: red","margin: 0 auto","display: inline","An opacity below 1 (as well as transform, filter and position: fixed) creates a stacking context, which can trap child z-index values.")
M('a','k',"What does grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)) do?","Creates as many columns of at least 200px as fit, and stretches them to fill the row","Creates exactly 200 columns","Creates one column of 200px","Makes every item 200px wide with gaps","auto-fit packs as many tracks as fit and collapses empty ones. 1fr lets the columns share leftover space.")
M('a','k',"A flex item containing a long unbroken word refuses to shrink and overflows its container. What is the usual fix?","min-width: 0 on the flex item","flex-grow: 0 on the container","display: block on the item","align-items: stretch","A flex item has min-width: auto, which stops it shrinking below its content. Setting min-width: 0 lets it shrink.")
M('a','k',"A position: sticky element never sticks. What is the most likely cause?","An ancestor has overflow set to hidden, auto or scroll, or no top/bottom offset is set","The element has no background","The page has no media query","The element is display: block","Sticky needs an offset such as top: 0 and a scrolling ancestor that is not clipped by an overflow rule on an intermediate ancestor.")
M('a','k',"What is flex: 1 shorthand for?","flex: 1 1 0%","flex: 0 0 auto","flex: 1 0 auto","flex: 0 1 1","flex: 1 means grow 1, shrink 1, basis 0%, so items share the free space equally.")
M('a','k',"Which declaration keeps a box at a 16:9 shape as its width changes?","aspect-ratio: 16 / 9","ratio: 16:9","proportion: 16-9","scale-ratio: 1.78","aspect-ratio lets the browser compute the height from the width.")
topic('Selectors & Specificity')
M('a','k',"What is the specificity of a selector written inside :where()?","Zero","The same as the most specific argument","One class","One element",":where() always contributes zero specificity, which makes it ideal for easily overridden defaults.")
M('a','k',"What is the specificity of :is(h1, #title) span?","(1,0,1): the most specific argument counts","(0,0,2)","(0,1,1)","(0,0,1)","For :is() the specificity is that of its most specific argument, here the id, plus the span element.")
M('a','k',"Normal (non-!important) declarations in two cascade layers conflict. Which layer wins?","The layer declared later","The layer declared first","The one with the higher specificity selector","The one with more rules","Layer order beats specificity. Styles outside any layer beat all layered styles.")
topic('Variables & Modern CSS')
M('a','k',"What is required on an element before a container query can use its size?","container-type (for example inline-size)","display: container","position: container","contain-size: true","A container query looks up to the nearest ancestor with container-type set.")
M('a','k',"What does clamp(1rem, 2vw, 2rem) return?","The preferred value 2vw, limited to between 1rem and 2rem","Always 2vw","The largest of the three values","The average of the three values","clamp(min, preferred, max) keeps the middle value within the minimum and maximum.")
M('a','k',"What is will-change meant for?","Hinting to the browser which property is about to change so it can optimise","Forcing a property to animate","Preventing a property from changing","Setting a default value","Overusing will-change wastes memory, so apply it sparingly.")
M('a','o',"A parent has font-size: 20px. Its child has font-size: 1.5em and the grandchild also has font-size: 1.5em. What is the grandchild's computed font size?","45px","30px","22.5px","50px","em compounds: child = 20 × 1.5 = 30px, grandchild = 30 × 1.5 = 45px.")
M('a','k',"Which of these properties is inherited by default?","line-height","margin","border","background-color","Text-related properties such as color, font and line-height are inherited. Box properties such as margin and border are not.")
M('a','s',"A card grid should have columns that never get narrower than 250px and fill the available space. Which CSS does this without media queries?","grid-template-columns: repeat(auto-fill, minmax(250px, 1fr))","grid-template-columns: 250px","display: flex; width: 250px","columns: 250","auto-fill with minmax creates as many 250px-minimum columns as fit and shares the remainder.")
